package cn.mop.api;
import cn.mop.domain.DomainException;
import cn.mop.domain.dashboard.DashboardAvailabilitySnapshot;
import cn.mop.domain.dashboard.DashboardAvailabilitySnapshot.*;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class DashboardAvailabilitySnapshotTest {
    final UUID tenant=UUID.fromString("7b000000-0000-4000-8000-000000000001"),actor=UUID.fromString("7b000000-0000-4000-8000-000000000002");
    final Instant now=Instant.parse("2026-10-04T16:30:00.123Z");
    DashboardAvailabilitySnapshot snapshot(TrendWindow window){return new DashboardAvailabilitySnapshot(tenant,actor,7,now,window);}
    @Test void exactSixKpisAndSixPanelsRetainContractOrder(){var s=snapshot(TrendWindow.HOURS_24);assertEquals(List.of(KpiId.values()),s.kpis().stream().map(Kpi::id).toList());assertEquals(List.of(PanelId.values()),s.panels().stream().map(Panel::id).toList());assertFalse(s.layoutCustomizationAllowed());assertEquals("MOP_FIXED_DASHBOARD_V1",s.layoutVersion());assertEquals(30,s.contractRefreshSeconds());}
    @Test void unavailableMetricsNeverBecomeZeroHealthyOrDelivered(){for(var k:snapshot(TrendWindow.HOURS_24).kpis()){assertNull(k.value());assertNull(k.sampleCount());assertNull(k.sampledAt());assertNull(k.metricVersion());assertNull(k.thresholdBreached());assertNull(k.drilldownPath());assertEquals("UNKNOWN",k.state());assertEquals("NOT_IMPLEMENTED",k.readerStatus());assertTrue(k.detailCounts().values().stream().allMatch(Objects::isNull));}}
    @Test void unknownStatusAndProblemBreakdownsAreNamedAndNeverCombined(){var s=snapshot(TrendWindow.HOURS_24);assertEquals(List.of("normal","unknown","total"),new ArrayList<>(s.kpis().get(0).detailCounts().keySet()));assertEquals(List.of("disaster","severe","average","warning","information"),new ArrayList<>(s.kpis().get(1).detailCounts().keySet()));assertEquals(Set.of("overdue_sla"),s.kpis().get(3).detailCounts().keySet());assertEquals(Set.of("accepted","delivered"),s.kpis().get(5).detailCounts().keySet());}
    @Test void missingDatasetsAreNullNotEmptyArraysClaimingNoIncidents(){for(var p:snapshot(TrendWindow.DAYS_30).panels()){assertNull(p.items());assertNull(p.sampleCount());assertNull(p.sampledAt());assertEquals("UNKNOWN",p.state());}var p=snapshot(TrendWindow.HOURS_24).panels();assertEquals(8,p.get(2).contractItemLimit());assertEquals(7,p.get(3).contractItemLimit());assertEquals(5,p.get(4).contractItemLimit());assertEquals(5,p.get(5).contractItemLimit());}
    @Test void trendRangesUseExact24Hour7DayAnd30DayPeriods(){for(var w:TrendWindow.values()){var s=snapshot(w);assertEquals(now,s.trendPeriod().to());assertEquals(switch(w){case HOURS_24->24;case DAYS_7->168;case DAYS_30->720;},Duration.between(s.trendPeriod().from(),now).toHours());}}
    @Test void monthToDateUsesShanghaiMonthBoundaryNotUtcOrBrowserZone(){var s=snapshot(TrendWindow.DAYS_7);assertEquals(Instant.parse("2026-09-30T16:00:00Z"),s.monthStart());assertEquals(s.monthStart(),s.kpis().get(2).period().from());assertEquals(now,s.kpis().get(2).period().to());assertEquals("Asia/Shanghai",s.timezone());}
    @Test void exactMonthBoundaryIsExplicitlyEmptyWithoutProducingZeroAvailability(){var s=new DashboardAvailabilitySnapshot(tenant,actor,1,Instant.parse("2026-09-30T16:00:00Z"),TrendWindow.DAYS_30);assertTrue(s.monthWindowEmpty());assertEquals(s.generatedAt(),s.kpis().get(2).period().from());assertEquals(s.generatedAt(),s.kpis().get(2).period().to());assertNull(s.kpis().get(2).value());assertNull(s.kpis().get(2).sampleCount());}
    @Test void last24HoursDoNotExpandWhenTrendChangesTo30Days(){var s=snapshot(TrendWindow.DAYS_30);for(int n:List.of(4,5))assertEquals(Duration.ofHours(24),Duration.between(s.kpis().get(n).period().from(),s.kpis().get(n).period().to()));assertEquals(s.last24Hours(),s.panels().get(2).period());}
    @Test void projectionCollectionsAreImmutableAndKnownCountsCannotEnterMissingReader(){var s=snapshot(TrendWindow.HOURS_24);assertThrows(UnsupportedOperationException.class,()->s.kpis().clear());assertThrows(UnsupportedOperationException.class,()->s.panels().clear());assertThrows(UnsupportedOperationException.class,()->s.kpis().get(0).detailCounts().put("normal",0L));assertThrows(DomainException.class,()->new Kpi(KpiId.ASSET_ONLINE_RATE,"PERCENT",null,"MISSING",Map.of("normal",0L)));}
    @Test void scopePermissionWindowAndSubmillisecondClockAreRequired(){for(long v:new long[]{0,-1,9007199254740992L})assertThrows(DomainException.class,()->new DashboardAvailabilitySnapshot(tenant,actor,v,now,TrendWindow.HOURS_24));assertThrows(DomainException.class,()->new DashboardAvailabilitySnapshot(null,actor,1,now,TrendWindow.HOURS_24));assertThrows(DomainException.class,()->new DashboardAvailabilitySnapshot(tenant,null,1,now,TrendWindow.HOURS_24));assertThrows(DomainException.class,()->new DashboardAvailabilitySnapshot(tenant,actor,1,now,null));assertThrows(DomainException.class,()->new DashboardAvailabilitySnapshot(tenant,actor,1,now.plusNanos(1),TrendWindow.HOURS_24));}
    @Test void protocolBoundaryDoesNotClampAnUnrepresentablePriorWindow(){assertThrows(DomainException.class,()->new DashboardAvailabilitySnapshot(tenant,actor,1,Instant.parse("0001-01-01T00:00:00Z"),TrendWindow.DAYS_30));assertThrows(DomainException.class,()->new DashboardAvailabilitySnapshot(tenant,actor,1,Instant.parse("9999-12-31T23:59:59.999Z"),TrendWindow.HOURS_24));}
    @Test void authorizationAndDatabaseClockAreNotMetricSamplesOrVerifiedTimeSync(){var s=snapshot(TrendWindow.DAYS_7);assertEquals(tenant,s.tenantId());assertEquals(actor,s.actorId());assertEquals(7,s.permissionVersion());assertEquals(now,s.generatedAt());assertFalse(s.metricSamplesLoaded());assertFalse(s.clockAccuracyVerified());assertEquals("POSTGRESQL_AUTHORIZATION_AND_CLOCK_ONLY",s.source());assertEquals("CURRENT_AUTHORIZED_TENANT",s.scope());assertEquals("NOT_IMPLEMENTED",s.formalMetricStatus());}
}
